#!/usr/bin/env python3
"""GF-010 deterministic A-T acceptance using isolated local Git remotes."""

from __future__ import annotations
import argparse, hashlib, json, os, pathlib, shutil, subprocess, tempfile, time

ROOT = pathlib.Path(__file__).resolve().parents[2]
CLI = ROOT / "scripts/gf-approve.sh"
CANDIDATE_IDENTITY_VERSION = 2
NAMES = {
 "A":"approval_required", "B":"approved_direct_integration", "C":"no_repeated_approval", "D":"candidate_changed",
 "E":"remote_advances_cleanly", "F":"remote_conflict", "G":"crash_after_push", "H":"push_failure_before_remote",
 "I":"ambiguous_push_reconcile", "J":"adoption_clean", "K":"adoption_unrelated", "L":"approval_bundle",
 "M":"multiple_pending", "N":"already_integrated", "O":"pr_policy", "P":"external_reviewer_policy",
 "Q":"post_integration_validation_failure", "R":"cleanup", "S":"scheduler_cannot_approve", "T":"force_push_forbidden",
 "U":"git_stable_candidate_identity"}

def run(args, cwd, env=None, check=True):
    merged=os.environ.copy(); merged.update(env or {})
    result=subprocess.run(args,cwd=cwd,env=merged,text=True,capture_output=True)
    if check and result.returncode: raise RuntimeError(f"{args}: {result.stderr}")
    return result

def git(repo,*args,check=True): return run(["git",*args],repo,check=check).stdout.strip()

def adoption_fingerprint(repo, paths, base):
    identities={}
    for relative in sorted(paths):
        target=repo/relative
        if not target.exists(): identities[relative]="absent"; continue
        mode="100755" if target.stat().st_mode & 0o100 else "100644"
        identities[relative]=f"file:{mode}:{hashlib.sha256(target.read_bytes()).hexdigest()}"
    return hashlib.sha256(json.dumps({"candidate_identity_version":CANDIDATE_IDENTITY_VERSION,"base_sha":base,"paths":identities},sort_keys=True,separators=(",",":")).encode()).hexdigest()

def fixture(root, name, adoption=False, units=1, mode="direct", external=False, validator_body=None, with_milestone_gates=False, shared_dependencies=False, adapter="fixture", evidence_in_adoption=False):
    case=root/name; remote=case/"remote.git"; repo=case/"repo"; state=case/"state"; artifacts=case/"artifacts"
    case.mkdir(parents=True); run(["git","init","--bare","-q",str(remote)],case)
    run(["git","init","-q","-b","main",str(repo)],case)
    git(repo,"config","user.name","GF-010 Test"); git(repo,"config","user.email","gf010@test.invalid")
    if shared_dependencies:
        validator_body="#!/usr/bin/env bash\nset -e\ntest -L node_modules\ntest \"$(cat node_modules/fake-tool.txt)\" = fixture-tool\n"
        (repo/".gitignore").write_text("node_modules/\n"); (repo/"package.json").write_text('{"name":"fixture","private":true}\n'); (repo/"package-lock.json").write_text('{"name":"fixture","lockfileVersion":3}\n'); (repo/"node_modules").mkdir(); (repo/"node_modules/fake-tool.txt").write_text("fixture-tool\n")
    (repo/"validate.sh").write_text(validator_body or "#!/usr/bin/env bash\nset -e\ntest -f feature-0.txt\n",encoding="utf-8"); (repo/"validate.sh").chmod(0o755)
    (repo/"base.txt").write_text("base\n",encoding="utf-8"); git(repo,"add","."); git(repo,"commit","-q","-m","base"); base=git(repo,"rev-parse","HEAD")
    git(repo,"remote","add","origin",str(remote)); git(repo,"push","-q","-u","origin","main")
    evidence=[]
    for index in range(units):
        path=(repo if evidence_in_adoption else case)/f"evidence-{index}.json"; path.write_text(json.dumps({"status":"pass"})+"\n"); evidence.append(path)
    candidate=[]; groups=[]
    if adoption:
        (repo/"feature-0.txt").write_text("approved feature 0\n",encoding="utf-8")
        adoption_paths=["feature-0.txt"]+[f"evidence-{index}.json" for index in range(units) if evidence_in_adoption]
        groups=[{"id":"UNIT","unit_ids":[f"UNIT-{i}" for i in range(units)],"commit_message":"adopt feature","paths":adoption_paths}]
    else:
        for index in range(units):
            relative=f"feature-{index}.txt"; (repo/relative).write_text(f"approved feature {index}\n",encoding="utf-8")
            git(repo,"add",relative); git(repo,"commit","-q","-m",f"candidate {index}"); sha=git(repo,"rev-parse","HEAD"); tree=git(repo,"rev-parse","HEAD^{tree}"); candidate.append({"sha":sha,"tree_sha":tree,"unit_ids":[f"UNIT-{index}"],"paths":[relative]})
        git(repo,"reset","-q","--hard",base)
    for index,path in enumerate(evidence):
        value={"status":"pass","unit_id":f"UNIT-{index}"}
        if not adoption: value["candidate_sha"]=candidate[index]["sha"]
        path.write_text(json.dumps(value,sort_keys=True)+"\n",encoding="utf-8")
    integration={"mode":mode,"allow_force_push":False,"verify_remote":True}
    policy_integration={"repository":str(repo),"manifest_roots":[str(case)],"allow_untracked_manifests_for_fixtures":True,"remote":"origin","remote_url":str(remote),"push_url":str(remote),"target_branch":"main",**integration,"validation_commands":[["./validate.sh"]]}
    if shared_dependencies: policy_integration["validation_dependency_mode"]="shared_locked_node_modules"
    if mode=="pull_request":
        integration.update({"pr_adapter":adapter,"external_reviewer_required":external,"merge_method":"merge","required_checks":True,"require_strict_base_checks":True})
        policy_integration.update({"pr_adapter":adapter,"external_reviewer_required":external,"merge_method":"merge","required_checks":True,"require_strict_base_checks":True})
        if adapter=="github": integration["github_repository"]="fixture/repo"; policy_integration["github_repository"]="fixture/repo"
    policy=case/"integration-policy.json"; policy.write_text(json.dumps({"schema_version":1,"repositories":{"fixture":policy_integration}},indent=2)+"\n")
    manifest={"schema_version":1,"approval_id":name,"approval_type":"adoption_bundle" if adoption else "candidate_bundle","project_id":"fixture","repository":str(repo),"base_sha":base,"units":[{"id":f"UNIT-{i}","validation_evidence":str(evidence[i]),"critic_required":False} for i in range(units)],"evidence_bindings":[{"unit_id":f"UNIT-{i}","validation_sha256":hashlib.sha256(evidence[i].read_bytes()).hexdigest()} for i in range(units)],"remote":"origin","target_branch":"main","integration":integration,"validation_commands":[["./validate.sh"]]}
    if adoption:
        manifest["adoption"]={"groups":groups}; manifest["candidate_identity_version"]=CANDIDATE_IDENTITY_VERSION; manifest["candidate_patch_sha256"]=adoption_fingerprint(repo,groups[0]["paths"],base)
    else: manifest["candidate_commits"]=candidate
    milestone_state=case/"milestones"
    if with_milestone_gates:
        manifest["milestone_gates"]=[]
        for index in range(units):
            milestone_id=f"GF-FIXTURE-{name.upper()}-{index}"; package=case/"milestone-packages"/milestone_id; (package/"tasks").mkdir(parents=True)
            (package/"design.md").write_text("# Fixture design\n"); (package/"guidelines.md").write_text("# Fixture guidelines\n")
            milestone_value={"id":milestone_id,"title":f"Fixture {index}","version":1,"repository":{"name":"fixture","path":str(repo)},"design":"design.md","guidelines":"guidelines.md","tasks":[f"tasks/UNIT-{index}.json"],"completion_gate":"human_review"}
            task_value={"id":f"UNIT-{index}","title":f"Unit {index}","objective":"Exercise approval gate","depends_on":[],"allowed_scope":[f"feature-{index}.txt"],"acceptance":["fixture passes"],"retry_policy":{"max_attempts":1},"on_failure":"escalate"}
            (package/"milestone.json").write_text(json.dumps(milestone_value,indent=2)+"\n"); (package/f"tasks/UNIT-{index}.json").write_text(json.dumps(task_value,indent=2)+"\n")
            milestone_env={"GF_MILESTONE_STATE_ROOT":str(milestone_state)}
            run([str(ROOT/"scripts/gf-milestone.sh"),"init",str(package)],case,env=milestone_env)
            run([str(ROOT/"scripts/gf-milestone.sh"),"transition",milestone_id,f"UNIT-{index}","running"],case,env=milestone_env)
            run([str(ROOT/"scripts/gf-milestone.sh"),"transition",milestone_id,f"UNIT-{index}","pass"],case,env=milestone_env)
            manifest["milestone_gates"].append({"milestone_id":milestone_id,"task_ids":[f"UNIT-{index}"]})
    manifest_path=case/"manifest.json"; manifest_path.write_text(json.dumps(manifest,indent=2)+"\n")
    env={"GF_APPROVAL_STATE_ROOT":str(state),"GF_APPROVAL_ARTIFACT_ROOT":str(artifacts),"GF_APPROVAL_POLICY_CONFIG":str(policy),"GF_MILESTONE_STATE_ROOT":str(milestone_state)}
    return case,repo,remote,manifest_path,env,base

def cli(case, env, *args, check=True, fault=None, extra_env=None):
    use=dict(env)
    if fault: use.update({"GF_GF010_ENABLE_TEST_HOOKS":"1","GF_GF010_FAULT":fault})
    use.update(extra_env or {})
    return run([str(CLI),*args],case,env=use,check=check)

def record(results, letter, passed, detail=""):
    results.append({"test":letter,"name":NAMES[letter],"status":"pass" if passed else "fail","detail":detail or None})

