    case,repo,remote,manifest,env,base=fixture(root,f"i{number}-changed",adoption=True); cli(case,env,"create",str(manifest)); (repo/"feature-0.txt").write_text("changed after bundle\n")
    changed=cli(case,env,"approve",f"i{number}-changed","--source","operator_agent_explicit_human",check=False)
    case2,repo2,remote2,manifest2,env2,base2=fixture(root,f"i{number}-evidence-changed"); cli(case2,env2,"create",str(manifest2)); (case2/"evidence-0.json").write_text(json.dumps({"status":"pass","changed":True})+"\n"); evidence_changed=cli(case2,env2,"approve",f"i{number}-evidence-changed","--source","operator_agent_explicit_human",check=False)
    record(results,"D",changed.returncode!=0 and "CANDIDATE_CHANGED" in changed.stderr and evidence_changed.returncode!=0 and "EVIDENCE_CHANGED" in evidence_changed.stderr)

    case,repo,remote,manifest,env,base=fixture(root,f"i{number}-advance"); cli(case,env,"create",str(manifest))
