    case,repo,remote,manifest,env,base=fixture(root,f"i{number}-crash"); cli(case,env,"create",str(manifest)); crashed=cli(case,env,"approve",f"i{number}-crash","--source","operator_agent_explicit_human",check=False,fault="crash_after_push"); crash_state_path=pathlib.Path(env["GF_APPROVAL_STATE_ROOT"])/f"i{number}-crash.json"; pre_reconcile=json.loads(crash_state_path.read_text()); orphan=pathlib.Path(pre_reconcile["worktree_path"]); reconciled=cli(case,env,"reconcile",f"i{number}-crash"); state=json.loads(crash_state_path.read_text()); crash_receipt=(pathlib.Path(env["GF_APPROVAL_ARTIFACT_ROOT"])/f"i{number}-crash"/"result.json").is_file(); crash_cleanup=orphan.exists() is False and state.get("cleanup",{}).get("temporary_worktree_removed") is True; record(results,"G",crashed.returncode==97 and crash_cleanup and crash_receipt and reconciled.returncode==0 and state["integration_status"]=="INTEGRATED")
