    g_result=results[-1]; g_result["status"]="pass" if g_result["status"]=="pass" and evidence_recovery_safe else "fail"; g_result["detail"]=None if g_result["status"]=="pass" else "crash recovery accepted missing bound evidence or failed cleanup"
