    case,repo,remote,manifest,env,base=fixture(root,f"i{number}-crash-rewritten"); cli(case,env,"create",str(manifest)); rewritten_crash=cli(case,env,"approve",f"i{number}-crash-rewritten","--source","operator_agent_explicit_human",check=False,fault="crash_after_push"); other=case/"other"; run(["git","clone","-q",str(remote),str(other)],case); git(other,"checkout","-q","-b","main","origin/main"); git(other,"config","user.name","Remote"); git(other,"config","user.email","remote@test"); git(other,"reset","-q","--hard",base); (other/"rewrite.txt").write_text("non-descendant\n"); git(other,"add","."); git(other,"commit","-q","-m","rewrite remote"); git(other,"push","-q","--force","origin","main"); rewritten=cli(case,env,"reconcile",f"i{number}-crash-rewritten",check=False); rewritten_state=json.loads((pathlib.Path(env["GF_APPROVAL_STATE_ROOT"])/f"i{number}-crash-rewritten.json").read_text()); rewrite_ok=rewritten_crash.returncode==97 and rewritten.returncode!=0 and rewritten_state["failure_class"]=="REMOTE_MOVED_AFTER_PUSH" and [item["name"] for item in rewritten_state["checkpoints"]].count("PUSH_STARTED")==1; g_result["status"]="pass" if g_result["status"]=="pass" and rewrite_ok else "fail"; g_result["detail"]=None if g_result["status"]=="pass" else "descendant/non-descendant post-push movement was not fail-closed"

